import json
import random
from pathlib import Path

# ========== Configuration ==========
SEED = 42
VAL_RATIO = 0.1
root = Path("/Users/qianliaopeng/VLA_local/VLA-project")
# Raw annotation file generated by batch_gen_subtask_list.py
input_raw = root / "exported_frames" / "train_episode_with_subtask_list.jsonl"
train_out = root / "exported_frames" / "dataset_subtask_train.jsonl"
val_out = root / "exported_frames" / "dataset_subtask_val.jsonl"
# Required keys matching raw jsonl
REQUIRED_KEYS = {"image_paths", "language_instruction", "subtask_list"}
MIN_SUBTASK_COUNT = 2
# ===================================

random.seed(SEED)


def read_jsonl(path: Path):
    """Read raw jsonl and return list of raw dict items."""
    raw_data = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                item = json.loads(line)
                raw_data.append(item)
            except Exception as e:
                print(f"Skip invalid json line, parse error: {e}")
    return raw_data


def clean_subtask_text(text: str) -> str:
    """Strip whitespace and remove useless explanatory prefix/suffix for subtask string."""
    text = text.strip()
    return text


def filter_and_clean_samples(raw_list):
    """
    Apply all filtering rules:
    1. Check all required keys exist
    2. subtask_list must be list type
    3. Clean each subtask string, drop empty subtask
    4. Keep samples with at least MIN_SUBTASK_COUNT valid subtasks
    5. Check image file exists (support relative path based on project root)
    6. Deduplicate by (language_instruction, image path) pair
    """
    valid_samples = []
    seen_pairs = set()

    for item in raw_list:
        if not REQUIRED_KEYS.issubset(item.keys()):
            continue

        img_str = item["image_paths"]
        instruction = item["language_instruction"].strip()
        subtask_list = item["subtask_list"]

        if not isinstance(subtask_list, list):
            continue
        if not instruction:
            continue

        cleaned_subtasks = []
        for st in subtask_list:
            if isinstance(st, str):
                c_st = clean_subtask_text(st)
                if c_st:
                    cleaned_subtasks.append(c_st)
        if len(cleaned_subtasks) < MIN_SUBTASK_COUNT:
            continue

        # image_paths may be a list, take the first one
        if isinstance(img_str, list):
            img_str = img_str[0]
        img_path = Path(img_str)
        if not img_path.is_absolute():
            img_path = root / img_path

        if not img_path.exists():
            continue

        dedup_key = (instruction, str(img_path))
        if dedup_key in seen_pairs:
            continue
        seen_pairs.add(dedup_key)

        # Add alias keys for training dataloader compatibility
        item["instruction"] = instruction
        item["image"] = img_str
        item["subtask_list"] = cleaned_subtasks
        valid_samples.append(item)
    return valid_samples


def write_jsonl(save_path: Path, data_list):
    """Write list of dict into jsonl file."""
    with open(save_path, "w", encoding="utf-8") as f:
        for d in data_list:
            f.write(json.dumps(d, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    raw_samples = read_jsonl(input_raw)
    print(f"Total raw samples loaded: {len(raw_samples)}")

    filtered_samples = filter_and_clean_samples(raw_samples)
    print(f"Valid samples after filtering: {len(filtered_samples)}")

    random.shuffle(filtered_samples)
    split_index = int(len(filtered_samples) * (1 - VAL_RATIO))
    train_set = filtered_samples[:split_index]
    val_set = filtered_samples[split_index:]

    write_jsonl(train_out, train_set)
    write_jsonl(val_out, val_set)

    print(f"Train set saved: {len(train_set)} samples -> {train_out}")
    print(f"Val set saved:   {len(val_set)} samples -> {val_out}")
